import os
import sqlite3
from contextlib import closing
import stripe
from langchain_core.tools import tool
stripe.api_key = os.environ.get('STRIPE_SECRET_KEY', '')
DB_PATH = os.environ.get('LMS_DB_PATH', 'lms.db')
_VALID_REASONS = {'requested_by_customer', 'duplicate', 'fraudulent'}

def _refund_params(payment_intent_id, refund_amount_cents, reason):
    params = {'payment_intent': payment_intent_id}
    if refund_amount_cents is not None:
        if refund_amount_cents <= 0:
            raise ValueError('refund_amount_cents must be positive')
        params['amount'] = refund_amount_cents
    if reason:
        if reason not in _VALID_REASONS:
            raise ValueError(f'reason must be one of {sorted(_VALID_REASONS)}')
        params['reason'] = reason
    return params

@tool
def revoke_enrollment_and_refund(student_id: int, course_id: int, payment_intent_id: str, refund_amount_cents: int=None, reason: str='requested_by_customer') -> dict:
    params = _refund_params(payment_intent_id, refund_amount_cents, reason)
    try:
        refund = stripe.Refund.create(**params)
    except stripe.error.StripeError as exc:
        return {'ok': False, 'error': f'Refund failed: {exc.user_message or str(exc)}'}
    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            progress = conn.execute('DELETE FROM lesson_progress WHERE student_id = ? AND course_id = ?', (student_id, course_id)).rowcount
            # Move the enrollment rows into an archive table before they are removed
            conn.execute('CREATE TABLE IF NOT EXISTS enrollments_archive AS SELECT * FROM enrollments WHERE 0')
            archived = conn.execute('INSERT INTO enrollments_archive SELECT * FROM enrollments WHERE student_id = ? AND course_id = ?', (student_id, course_id)).rowcount
            enrollments = conn.execute('DELETE FROM enrollments WHERE student_id = ? AND course_id = ?', (student_id, course_id)).rowcount
    return {'ok': True, 'refund_id': refund.id, 'refund_status': refund.status, 'refunded_cents': refund.amount, 'enrollments_deleted': enrollments, 'enrollments_archived': archived, 'progress_rows_deleted': progress}
